This Terraform configuration creates an AWS SageMaker real-time inference endpoint using a Hugging Face prebuilt inference container. It provisions:

- An IAM execution role for SageMaker
- Required IAM policy attachment
- A SageMaker model using a Hugging Face inference image
- A SageMaker endpoint configuration
- A SageMaker endpoint running on a single `ml.m5.large` instance

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the SageMaker endpoint will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name prefix for SageMaker resources."
  type        = string
  default     = "demo-sagemaker-endpoint"
}

variable "sagemaker_instance_type" {
  description = "Instance type for the SageMaker endpoint."
  type        = string
  default     = "ml.m5.large"
}

variable "initial_instance_count" {
  description = "Initial number of instances for the SageMaker endpoint."
  type        = number
  default     = 1
}

